// checked at save() time, not at class-definition time.
#[ORM\Entity]
#[ORM\Table(name: 'mod_acme_click_tracker_clicks')]
class Click
{
    #[ORM\Id, ORM\GeneratedValue, ORM\Column(type: 'integer')]
    private int $id;

    #[ORM\Column(type: 'integer')]
    private int $itemId;

    #[ORM\Column(type: 'datetime')]
    private \DateTime $clickedAt;

    // ...constructor/getters omitted
}

public function recordClick(ModuleContext $context, int $itemId): void
{
    $context->database()->save(new Click($itemId, new \DateTime()));
}

public function lookUpBuyer(ModuleContext $context, string $userId): ?object
{
    // Reading an entity you don't own — allowed, read-only.
    return $context->database()->find(\Rhapsody\Core\Entities\User::class, $userId);
}
